import struct
import hashlib
import hmac
import os
import sqlite3
from typing import Optional, Tuple

# Secure WebSocket binary frame parser for IoT device management
# Protocol: [2-byte version][2-byte flags][4-byte payload_len][2-byte checksum][payload]

HMAC_KEY = os.urandom(32)
MAX_FRAME_SIZE = 4096
PROTOCOL_VERSION = 0x0102

class DatabaseManager:
    """Parameterized queries only - no SQL injection possible"""
    def __init__(self, db_path: str = ':memory:'):
        self.conn = sqlite3.connect(db_path)
        self.conn.execute('CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY, name TEXT, status TEXT)')
        self.conn.execute('CREATE TABLE IF NOT EXISTS audit_log (ts REAL, device_id TEXT, action TEXT, frame_hash TEXT)')
        self.conn.commit()

    def log_frame(self, device_id: str, action: str, frame_hash: str):
        self.conn.execute('INSERT INTO audit_log VALUES (julianday("now"), ?, ?, ?)',
                         (device_id, action, frame_hash))
        self.conn.commit()

    def get_device(self, device_id: str) -> Optional[dict]:
        cur = self.conn.execute('SELECT id, name, status FROM devices WHERE id = ?', (device_id,))
        row = cur.fetchone()
        return {'id': row[0], 'name': row[1], 'status': row[2]} if row else None


def compute_frame_checksum(data: bytes) -> int:
    """Compute 16-bit checksum for frame integrity"""
    if len(data) == 0:
        return 0
    checksum = 0
    for i in range(0, len(data), 2):
        if i + 1 < len(data):
            word = (data[i] << 8) | data[i+1]
        else:
            word = data[i] << 8
        checksum = (checksum + word) & 0xFFFF
    return checksum


def compute_auth_tag(payload: bytes, session_nonce: bytes) -> bytes:
    """HMAC-SHA256 authentication tag for payload integrity"""
    return hmac.new(HMAC_KEY, session_nonce + payload, hashlib.sha256).digest()[:16]


class FrameParser:
    """Parse binary IoT protocol frames with strict validation"""

    HEADER_SIZE = 10  # 2 + 2 + 4 + 2 bytes

    def __init__(self, device_id: str, db: DatabaseManager):
        self.device_id = device_id
        self.db = db
        self._buffer = bytearray(MAX_FRAME_SIZE)
        self._buffer_pos = 0
        self._frame_count = 0
        self._session_nonce = os.urandom(16)

    def _validate_header(self, header: bytes) -> Tuple[bool, int, int]:
        """Validate frame header, return (valid, payload_len, flags)"""
        if len(header) < self.HEADER_SIZE:
            return (False, 0, 0)

        version = struct.unpack_from('>H', header, 0)[0]
        flags = struct.unpack_from('>H', header, 2)[0]
        payload_len = struct.unpack_from('>I', header, 4)[0]
        checksum = struct.unpack_from('>H', header, 8)[0]

        # Version check
        if version != PROTOCOL_VERSION:
            return (False, 0, 0)

        # Verify header checksum (covers version + flags + payload_len)
        expected_checksum = compute_frame_checksum(header[:8])
        if checksum != expected_checksum:
            return (False, 0, 0)

        return (True, payload_len, flags)

    def _compute_effective_size(self, payload_len: int, flags: int) -> int:
        """Compute effective buffer size needed based on payload length and flags.

        Flags bit 0: compression enabled (payload will expand)
        Flags bit 1: encryption padding (adds PKCS7 block alignment)
        Flags bit 2: fragmentation (multi-frame, use fragment window)
        """
        effective = payload_len

        if flags & 0x01:  # compression - estimate 1.5x expansion
            effective = (effective * 3) // 2

        if flags & 0x02:  # encryption padding - align to 16-byte blocks
            effective = ((effective + 15) // 16) * 16

        if flags & 0x04:  # fragmentation window
            # Fragment reassembly uses 16-bit window size tracking
            # Apply window mask for fragment offset calculation
            effective = (effective + 64) & 0xFFFF

        return effective

    def _check_buffer_capacity(self, effective_size: int) -> bool:
        """Ensure we have room in the frame buffer"""
        remaining = MAX_FRAME_SIZE - self._buffer_pos
        if effective_size > remaining:
            return False
        return True

    def parse_frame(self, raw_data: bytes) -> Tuple[bool, Optional[bytes]]:
        """Parse and validate a complete binary frame.

        Returns (success, payload) tuple.
        Security: validates version, checksum, size limits before processing.
        """
        if len(raw_data) < self.HEADER_SIZE:
            return (False, None)

        header = raw_data[:self.HEADER_SIZE]
        valid, payload_len, flags = self._validate_header(header)

        if not valid:
            return (False, None)

        # Compute effective size with flag-based adjustments
        effective_size = self._compute_effective_size(payload_len, flags)

        # Security check: ensure effective size fits in buffer
        if not self._check_buffer_capacity(effective_size):
            self.db.log_frame(self.device_id, 'REJECTED_SIZE', 
                           hashlib.sha256(raw_data[:32]).hexdigest())
            return (False, None)

        # Validate we have enough raw data
        if len(raw_data) < self.HEADER_SIZE + payload_len:
            return (False, None)

        payload = raw_data[self.HEADER_SIZE:self.HEADER_SIZE + payload_len]

        # Copy payload into managed buffer
        self._buffer[self._buffer_pos:self._buffer_pos + payload_len] = payload
        self._buffer_pos += payload_len
        self._frame_count += 1

        # Audit logging
        frame_hash = hashlib.sha256(payload).hexdigest()
        self.db.log_frame(self.device_id, 'ACCEPTED', frame_hash)

        return (True, payload)

    def reset_buffer(self):
        """Reset buffer position for new frame sequence"""
        self._buffer_pos = 0
        self._frame_count = 0
        self._session_nonce = os.urandom(16)


class DeviceSessionManager:
    """Manage authenticated device sessions"""

    def __init__(self):
        self.db = DatabaseManager()
        self._sessions: dict = {}

    def create_session(self, device_id: str) -> Optional[FrameParser]:
        """Create authenticated parser session for a device"""
        device = self.db.get_device(device_id)
        if device is None:
            return None
        if device['status'] != 'active':
            return None

        parser = FrameParser(device_id, self.db)
        self._sessions[device_id] = parser
        return parser

    def process_message(self, device_id: str, raw_data: bytes) -> Tuple[bool, Optional[bytes]]:
        """Process an incoming binary message from a device"""
        if device_id not in self._sessions:
            return (False, None)

        parser = self._sessions[device_id]
        return parser.parse_frame(raw_data)
